package com.sabyeguyz.clinic.treatment; import com.sabyeguyz.clinic.patient.Patient; import com.sabyeguyz.clinic.appointment.Appointment; import com.sabyeguyz.clinic.staff.Staff; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="treatments") public class Treatment { @Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="treatment_gen") @SequenceGenerator(name="treatment_gen",sequenceName="treatment_id_seq",allocationSize=1) private Long id; @ManyToOne(optional=false) @JoinColumn(name="patient_id") private Patient patient; @ManyToOne @JoinColumn(name="appointment_id") private Appointment appointment; @ManyToOne @JoinColumn(name="staff_id") private Staff staff; @Column(nullable=false) private String service; @Column(nullable=false) private String note; @Column(name="created_at") private Instant createdAt=Instant.now(); protected Treatment(){} public Treatment(Patient p,Appointment a,Staff s,String service,String note){patient=p;appointment=a;staff=s;this.service=service;this.note=note;} public Long getId(){return id;} public Patient getPatient(){return patient;} public Appointment getAppointment(){return appointment;} public Staff getStaff(){return staff;} public String getService(){return service;} public String getNote(){return note;} }
